// Beast roster: types for public/data/roster.json (generated by `npm run beasts`)
// plus helpers to load it, decode silhouette masks and build the ordered sim
// roster described in SPEC.md section 3.

/** 0 = Magic, 1 = Hunter, 2 = Brute (same encoding as the Beasts registry). */
export type BeastType = 0 | 1 | 2;

export interface RosterEntry {
  speciesId: number;
  name: string;
  /** Art Hackathon species (featured pool). */
  featured: boolean;
  type: BeastType;
  /** 1..5 */
  tier: number;
  health: number;
  level: number;
  /** Onchain "Adventurers Killed" of the genesis token. */
  kills: number;
  /** 0..3, from `kills` (SPEC section 3). */
  aggr: number;
  creator: string;
  owner: string;
  description: string;
  genesisTokenId: string;
  /** Path (relative to the site root / BASE_URL) of frame 0 as PNG. */
  art: string;
  /** Path of the original animated GIF. */
  gif: string;
  artW: number;
  artH: number;
  frames: number;
  /** Crop rectangle in source-art pixels [x, y, w, h]; draw it scaled to `w` x `h`. */
  artBox: [number, number, number, number];
  /** Silhouette size in field pixels (w <= 64, h <= 56). */
  w: number;
  h: number;
  /** base64 of w*h bits, row-major, MSB-first per byte. */
  mask: string;
  /** u64 hex string: 8x8 occupancy of the 1 px dilated mask, bit cy*8+cx. */
  occ: string;
  maskWarning: string | null;
}

export interface Roster {
  version: 1;
  generatedAt: string;
  network: string;
  nft: string;
  registry: string;
  /** Entries [0, nFeatured) are featured, the rest are common. */
  nFeatured: number;
  entries: RosterEntry[];
}

/** Exactly the fields the sim consumes (SPEC section 3 RosterEntry). */
export interface SimRosterEntry {
  type: BeastType;
  tier: number;
  health: number;
  aggr: number;
  w: number;
  h: number;
  occ: bigint;
}

export const MAX_W = 64;
export const MAX_H = 56;

/** Fetch the generated roster (default `<BASE_URL>data/roster.json`, i.e. `/data/roster.json`). */
export async function loadRoster(url?: string): Promise<Roster> {
  const base: string = import.meta.env?.BASE_URL ?? '/';
  const res = await fetch(url ?? `${base}data/roster.json`);
  if (!res.ok) throw new Error(`loadRoster: HTTP ${res.status}`);
  const roster = (await res.json()) as Roster;
  if (roster.version !== 1) throw new Error(`loadRoster: unsupported version ${String(roster.version)}`);
  return roster;
}

/** Resolve an entry's relative asset path (`art` / `gif`) against Vite's BASE_URL. */
export function assetUrl(path: string): string {
  const base: string = import.meta.env?.BASE_URL ?? '/';
  return base + path;
}

function bytesToBase64(bytes: Uint8Array): string {
  let s = '';
  for (let i = 0; i < bytes.length; i++) s += String.fromCharCode(bytes[i]);
  return btoa(s);
}

function base64ToBytes(b64: string): Uint8Array {
  const s = atob(b64);
  const out = new Uint8Array(s.length);
  for (let i = 0; i < s.length; i++) out[i] = s.charCodeAt(i);
  return out;
}

/** Pack a w*h 0/1 mask into base64 (row-major, MSB-first per byte). */
export function encodeMask(mask: Uint8Array, w: number, h: number): string {
  const n = w * h;
  if (mask.length !== n) throw new Error(`encodeMask: expected ${n} values, got ${mask.length}`);
  const bytes = new Uint8Array(Math.ceil(n / 8));
  for (let i = 0; i < n; i++) if (mask[i]) bytes[i >> 3] |= 0x80 >> (i & 7);
  return bytesToBase64(bytes);
}

/** Unpack an entry's mask into a w*h Uint8Array of 0/1, row-major. */
export function decodeMask(entry: Pick<RosterEntry, 'mask' | 'w' | 'h'>): Uint8Array {
  const n = entry.w * entry.h;
  const bytes = base64ToBytes(entry.mask);
  if (bytes.length < Math.ceil(n / 8)) throw new Error('decodeMask: mask too short');
  const out = new Uint8Array(n);
  for (let i = 0; i < n; i++) out[i] = (bytes[i >> 3] >> (7 - (i & 7))) & 1;
  return out;
}

/** Square (Chebyshev) dilation of a w*h 0/1 mask by `r` pixels, clipped to the box. */
export function dilateMask(mask: Uint8Array, w: number, h: number, r = 1): Uint8Array {
  const out = new Uint8Array(w * h);
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      if (!mask[y * w + x]) continue;
      for (let dy = -r; dy <= r; dy++) {
        const yy = y + dy;
        if (yy < 0 || yy >= h) continue;
        for (let dx = -r; dx <= r; dx++) {
          const xx = x + dx;
          if (xx >= 0 && xx < w) out[yy * w + xx] = 1;
        }
      }
    }
  }
  return out;
}

/**
 * 8x8 occupancy of the mask dilated by `dilate` px: bit (cy*8+cx) is set if any
 * pixel falls in that cell, with cx = floor(lx*8/w), cy = floor(ly*8/h).
 */
export function computeOcc(mask: Uint8Array, w: number, h: number, dilate = 1): bigint {
  const m = dilate > 0 ? dilateMask(mask, w, h, dilate) : mask;
  let occ = 0n;
  for (let ly = 0; ly < h; ly++) {
    const cy = Math.floor((ly * 8) / h);
    for (let lx = 0; lx < w; lx++) {
      if (!m[ly * w + lx]) continue;
      const cx = Math.floor((lx * 8) / w);
      occ |= 1n << BigInt(cy * 8 + cx);
    }
  }
  return occ;
}

/** SPEC section 3: 0 if k == 0, 1 if k < 3, 2 if k < 7, else 3. */
export function aggrFromKills(k: number): number {
  if (k <= 0) return 0;
  if (k < 3) return 1;
  if (k < 7) return 2;
  return 3;
}

const clampInt = (v: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, Math.trunc(v)));

/**
 * Ordered roster for the sim: featured entries first (in roster order), then
 * common entries. The number of featured entries is `roster.nFeatured`.
 * `notoriety` optionally adds STATIC kills per speciesId on top of the onchain
 * kills before computing `aggr`.
 */
export function toSimRoster(
  roster: Roster,
  notoriety?: ReadonlyMap<number, number> | Readonly<Record<number, number>>,
): SimRosterEntry[] {
  const extra = (id: number): number => {
    if (!notoriety) return 0;
    const v = notoriety instanceof Map ? notoriety.get(id) : (notoriety as Readonly<Record<number, number>>)[id];
    return typeof v === 'number' && Number.isFinite(v) ? v : 0;
  };
  const ordered = [...roster.entries.filter((e) => e.featured), ...roster.entries.filter((e) => !e.featured)];
  return ordered.map((e) => simEntryOf(e, notoriety ? aggrFromKills(e.kills + extra(e.speciesId)) : undefined));
}

/** One roster entry as the sim consumes it. `aggr` overrides the entry's own value when given. */
export function simEntryOf(e: RosterEntry, aggr?: number): SimRosterEntry {
  return {
    type: clampInt(e.type, 0, 2) as BeastType,
    tier: clampInt(e.tier, 1, 5),
    health: clampInt(e.health, 0, 0xffff),
    aggr: aggr ?? clampInt(e.aggr, 0, 3),
    w: clampInt(e.w, 1, MAX_W),
    h: clampInt(e.h, 1, MAX_H),
    occ: BigInt(e.occ),
  };
}
